"use client";
import * as React from "react";
import { Icon } from "@/registry/p1/internal/icons";
import "./gallery.css";

export interface GalleryImage {
  src: string;
  caption: string;
}

export interface GalleryProps {
  heading: string;
  layout: "grid" | "masonry" | "filmstrip" | "carousel";
  columns: "2" | "3" | "4";
  gap: "tight" | "regular" | "wide";
  ratio: "1 / 1" | "4 / 3" | "3 / 2" | "16 / 9";
  radius: "none" | "soft" | "round";
  captions: "off" | "on";
  images: GalleryImage[];
}

const GAP_TOKEN: Record<GalleryProps["gap"], string> = {
  tight: "var(--p1-space-sm)",
  regular: "var(--p1-space-md)",
  wide: "var(--p1-space-xl)",
};

const RADIUS_CLASS: Record<GalleryProps["radius"], string> = {
  none: "",
  soft: "p1-gallery__img-wrap--soft",
  round: "p1-gallery__img-wrap--round",
};

const GalleryCarousel: React.FC<{
  images: GalleryImage[];
  radiusClass: string;
  ratio: string;
  captions: boolean;
}> = ({ images, radiusClass, ratio, captions }) => {
  const [i, setI] = React.useState(0);
  const n = images.length || 1;
  const idx = Math.min(i, n - 1);
  const go = (d: number) => setI((idx + d + n) % n);
  const im = images[idx] || ({} as GalleryImage);
  return (
    <div className="p1-gallery__carousel">
      <div className={`p1-gallery__img-wrap ${radiusClass}`} style={{ aspectRatio: ratio }}>
        <img src={im.src} alt={im.caption || ""} className="p1-gallery__img" />
        {n > 1 &&
          (["prev", "next"] as const).map((dir) => (
            <button
              key={dir}
              type="button"
              aria-label={dir}
              data-dir={dir}
              onClick={() => go(dir === "next" ? 1 : -1)}
              className="p1-gallery__nav"
            >
              <Icon name={dir === "prev" ? "chevron-left" : "chevron-right"} className="p1-gallery__nav-icon" />
            </button>
          ))}
        {captions && im.caption && (
          <div className="p1-gallery__caption-overlay">{im.caption}</div>
        )}
      </div>
      {n > 1 && (
        <div className="p1-gallery__dots">
          {images.map((_, di) => (
            <button
              key={di}
              type="button"
              aria-label={`Go to ${di + 1}`}
              data-active={di === idx ? "true" : undefined}
              onClick={() => setI(di)}
              className="p1-gallery__dot"
            />
          ))}
        </div>
      )}
    </div>
  );
};

export function GalleryRender({ heading, layout, columns, gap, ratio, radius, captions, images }: GalleryProps) {
  const imgs = images || [];
  const cols = Math.min(Number(columns) || 3, Math.max(1, imgs.length));
  const gapVal = GAP_TOKEN[gap];
  const radiusClass = RADIUS_CLASS[radius];
  const cap = captions === "on";

  const tile = (im: GalleryImage, key: number, extra?: React.CSSProperties) => (
    <figure key={key} className="p1-gallery__tile" style={extra}>
      <div className={`p1-gallery__img-wrap ${radiusClass}`}>
        <img
          src={im.src}
          alt={im.caption || ""}
          className="p1-gallery__img"
          style={{ aspectRatio: extra?.aspectRatio, height: extra?.height ?? "100%" }}
        />
      </div>
      {cap && im.caption && <figcaption className="p1-gallery__figcaption">{im.caption}</figcaption>}
    </figure>
  );

  let body: React.ReactNode;
  if (layout === "masonry") {
    body = (
      <div style={{ columnCount: cols, columnGap: gapVal }}>
        {imgs.map((im, i) => tile(im, i, { breakInside: "avoid", marginBlockEnd: gapVal }))}
      </div>
    );
  } else if (layout === "filmstrip") {
    body = (
      <div className="p1-gallery__filmstrip" style={{ gap: gapVal }}>
        {imgs.map((im, i) => tile(im, i, { flex: "none", width: 340, height: 240 }))}
      </div>
    );
  } else if (layout === "carousel") {
    body = <GalleryCarousel images={imgs} radiusClass={radiusClass} ratio={ratio} captions={cap} />;
  } else {
    body = (
      <div className="p1-gallery__grid" style={{ gap: gapVal, gridTemplateColumns: `repeat(${cols}, minmax(0,1fr))` }}>
        {imgs.map((im, i) => tile(im, i, { aspectRatio: ratio }))}
      </div>
    );
  }

  return (
    <div className="p1-gallery p1-block">
      <div className="p1-gallery__inner">
        {heading && <h2 className="p1-gallery__heading">{heading}</h2>}
        {imgs.length ? (
          body
        ) : (
          <div className="p1-gallery__empty">Add images in the inspector.</div>
        )}
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta, wireframe } from '../define-meta';
import { GalleryRender, type GalleryProps, type GalleryImage } from "./gallery";
export type { GalleryProps, GalleryImage };

export const GalleryBlock: ComponentConfig<GalleryProps> = {
  fields: {
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "A short section heading of 2–5 words. Plain text, sentence case." },
    },
    layout: {
      type: "select" as const,
      options: [
        { label: "Grid", value: "grid" },
        { label: "Masonry", value: "masonry" },
        { label: "Filmstrip", value: "filmstrip" },
        { label: "Carousel", value: "carousel" },
      ],
    },
    columns: {
      type: "select" as const,
      options: [
        { label: "2", value: "2" },
        { label: "3", value: "3" },
        { label: "4", value: "4" },
      ],
    },
    gap: {
      type: "select" as const,
      options: [
        { label: "Tight", value: "tight" },
        { label: "Regular", value: "regular" },
        { label: "Wide", value: "wide" },
      ],
    },
    ratio: {
      type: "select" as const,
      options: [
        { label: "1 / 1", value: "1 / 1" },
        { label: "4 / 3", value: "4 / 3" },
        { label: "3 / 2", value: "3 / 2" },
        { label: "16 / 9", value: "16 / 9" },
      ],
    },
    radius: {
      type: "select" as const,
      options: [
        { label: "None", value: "none" },
        { label: "Soft", value: "soft" },
        { label: "Round", value: "round" },
      ],
    },
    captions: {
      type: "radio" as const,
      options: [
        { label: "Off", value: "off" },
        { label: "On", value: "on" },
      ],
    },
    images: {
      type: "array" as const,
      arrayFields: {
        src: { type: "text" as const },
        caption: { type: "text" as const, contentEditable: true, visible: false },
      },
      defaultItemProps: { src: wireframe(800, 600), caption: "" },
      getItemSummary: (item: GalleryImage) => item.caption || "Image",
    },
  },
  defaultProps: {
    heading: "From the field",
    layout: "grid",
    columns: "3",
    gap: "regular",
    ratio: "4 / 3",
    radius: "soft",
    captions: "off",
    images: [
      { src: wireframe(800, 600), caption: "Team offsite" },
      { src: wireframe(800, 600), caption: "Workshop" },
      { src: wireframe(800, 600), caption: "Launch day" },
      { src: wireframe(800, 600), caption: "Planning" },
      { src: wireframe(800, 600), caption: "Standup" },
      { src: wireframe(800, 600), caption: "Ship it" },
    ],
  },
  render: GalleryRender,
};

export const meta = defineMeta({
  title: 'Gallery',
  description: 'Multi-image display in grid, masonry, filmstrip, or carousel layout with optional captions and configurable columns/gap/ratio; use for photo galleries.',
  categories: ["showcase"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-icons"],
});

.p1-gallery__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
}

.p1-gallery__heading {
  font-family: var(--p1-font-heading);
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  line-height: var(--p1-leading-tight);
  margin-block-end: var(--p1-space-lg);
}
@media (width >= 48rem) {
  .p1-gallery__heading { font-size: var(--p1-text-3xl); }
}

/* Shared image tile */
.p1-gallery__tile { margin: 0; }

.p1-gallery__img-wrap {
  background-color: var(--p1-surface-subtle);
  overflow: hidden;
  position: relative;
}
.p1-gallery__img-wrap--soft  { border-radius: var(--p1-radius-card); }
.p1-gallery__img-wrap--round { border-radius: var(--p1-radius-xl); }

.p1-gallery__img {
  display: block;
  inline-size: 100%;
  object-fit: cover;
}

.p1-gallery__figcaption {
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-sm);
  margin-block-start: var(--p1-space-sm);
}

/* Grid layout */
.p1-gallery__grid { display: grid; }

/* Filmstrip layout */
.p1-gallery__filmstrip {
  display: flex;
  overflow-x: auto;
  padding-block-end: var(--p1-space-sm);
}

/* Carousel */
.p1-gallery__carousel { position: relative; }

.p1-gallery__nav {
  align-items: center;
  background-color: color-mix(in oklch, var(--p1-surface-default) 90%, transparent);
  border: 0;
  border-radius: var(--p1-radius-pill);
  block-size: 2.75rem;
  box-shadow: var(--p1-shadow-md);
  cursor: pointer;
  display: grid;
  inline-size: 2.75rem;
  inset-block-start: 50%;
  place-items: center;
  position: absolute;
  transform: translateY(-50%);
}
.p1-gallery__nav[data-dir="prev"] { inset-inline-start: var(--p1-space-md); }
.p1-gallery__nav[data-dir="next"] { inset-inline-end: var(--p1-space-md); }

.p1-gallery__nav-icon {
  block-size: 1.25rem;
  inline-size: 1.25rem;
}

.p1-gallery__caption-overlay {
  background: linear-gradient(to top, var(--p1-overlay), transparent);
  bottom: 0;
  color: var(--p1-fg-inverse);
  inset-inline: 0;
  padding-block: var(--p1-space-md);
  padding-inline: var(--p1-space-md);
  padding-block-start: 2.5rem;
  position: absolute;
}

.p1-gallery__dots {
  display: flex;
  gap: var(--p1-space-sm);
  justify-content: center;
  margin-block-start: var(--p1-space-md);
}

.p1-gallery__dot {
  background-color: var(--p1-border-strong);
  block-size: var(--p1-space-sm);
  border: 0;
  border-radius: var(--p1-radius-pill);
  cursor: pointer;
  inline-size: var(--p1-space-sm);
  padding: 0;
}
@media (prefers-reduced-motion: no-preference) {
  .p1-gallery__dot { transition: inline-size 200ms ease, background-color 200ms ease; }
}
.p1-gallery__dot[data-active="true"] {
  background-color: var(--p1-accent);
  inline-size: 1.5rem;
}

.p1-gallery__empty {
  border: 1px dashed var(--p1-border);
  border-radius: var(--p1-radius-card);
  color: var(--p1-fg-muted);
  padding: var(--p1-space-lg);
  text-align: center;
}

